// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // 1. Fund the contract with some ether
        vm.deal(address(c), 1 ether);
        // 2. Call sudicideAnyone() as the owner
        vm.prank(c.__owner()); // using auto-generated getter for private __owner? No, __owner is private – cannot read. Instead, use __onlyOwner pattern: The owner is the deployer. We'll prank as address(this) since Test contract deployed C.
        // Actually, in setUp() we called new C() which sets msg.sender (the test contract) as owner.
        // So prank as address(this).
        vm.prank(address(this));
        c.sudicideAnyone();
        // 3. Assert that contract balance is 0 (no funds sent to address(0) means they are burned)
        assertTrue(address(c).balance == 0);
    }
}

