import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        address cAddress = address(c);
        bytes memory codeBefore = cAddress.code;

        (bool success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));

        bytes memory codeAfter = cAddress.code;

        if (success) {
            assertTrue(codeAfter.length == 0);
        } else {
            assertTrue(codeAfter.length == codeBefore.length);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        // try calling as owner – we deploy as owner in constructor, so prank to this test contract
        // The owner is the test contract (this) because new C() is called from setUp.
        // Actually, owner is this contract. So we can call directly without prank.
        // For fuzzing non-owner calls, we vm.prank to a random address.
        // We'll check that when caller is the owner, the call does NOT revert.
        // The reference does not revert; the bug reverts always => this detects it.
        bool reverted = false;
        if (caller == address(this)) {
            (bool success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
            reverted = !success;
        } else {
            vm.prank(caller);
            (bool success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
            reverted = !success;
        }
        // The rule: when owner calls, the call should NOT revert.
        assertTrue(caller != address(this) || !reverted, "Owner call must not revert");
    }
}

