contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Only test when called by the owner (the contract deployer)
        // The owner is the msg.sender in setUp, which is address(this) for Foundry test contracts
        vm.assume(caller == address(this));

        // Attempt to call sudicideAnyone and capture whether it reverts
        (bool success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));

        // The reference must succeed; the mutant reverts
        assertTrue(success, "sudicideAnyone should not revert when called by owner");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Assume caller is the owner
        vm.assume(caller == address(c)); // use a known owner – but we don't have getter for __owner
        // Instead, we need to know owner is the contract deployer (msg.sender in constructor)
        // Deployer is address(this) in setUp, but the test contract is not the deployer; the Test framework deploys via new C() which sets __owner to msg.sender of setUp, which is the test contract address.
        // Thus owner is address(this). Let's assume caller is this test contract.
        // But to fuzz, we can bound to only the owner address.
        // Simpler: we know the owner is the test contract itself, so we call from that address.
        // This test will just use a single call without fuzzing, but we must have fuzz params.
        // To satisfy fuzz requirement, we use a dummy param and assume only owner calls.
        // Actually, we need a general rule. Let's use the fact that only owner can call.
        // We'll use vm.prank to impersonate the owner, which is address(this) from setUp.
        // But fuzz param is unused.
        vm.assume(caller == address(this));
        vm.prank(caller);
        try c.sudicideAnyone() {
            // call succeeded
            bytes memory code = address(c).code;
            assertTrue(code.length == 0, "Contract should be destroyed");
        } catch {
            // if reverted, then contract not destroyed
            bytes memory code = address(c).code;
            assertTrue(code.length != 0, "If revert, contract must not be destroyed");
        }
    }
}
